/**
 * Turns an existing-Album review into format 3 when metadata lookup is first admitted for it: the review captures, while its
 * source is still current, what lookup values are compared with and what applying them must find unchanged. The capture is
 * server-only (`catalogCapture`); the draft gains the review-only values. This module reads the review service; the review service
 * never imports it.
 */
import type { ClientSession } from 'mongodb';
import { CatalogCreditValidationError, type CatalogCredit } from '../../models/catalogCredit';
import { legacyCreditsForUnmigratedOwner } from '../../services/catalog/catalogCreditService';
import { storedExpectedTracklist, type ExpectedTracklistRow } from '../../services/catalog/albumExpectedTracklist';
import { legacyDurationEvidence } from '../lookup/lookupRanking';
import { AdminImportError } from '../import/adminImportContract';
import { CATALOG_REVIEW_DRAFT_V3, type ImportArtistEntry, type ImportLabelEntry } from '../import/adminImportDraft';
import { catalogReviewSourceDisc, importDraftVersion, importDraftWritable } from '../import/adminImportDraftCompat';
import type { AdminImportDocument } from '../import/adminImportService';
import { storedDraftV2 } from '../import/adminImportValueState';
import { adminCatalogEditableFields } from './adminCatalogService';
import {
    catalogReviewCredits, catalogReviewEntryKey, convertLegacyCatalogReview, readableCatalogCapture, readCatalogReviewSource, readCatalogReviewSubjects
} from './adminCatalogReviewService';
import type { CatalogReviewCapture, CatalogReviewCapturedCredit, CatalogReviewCapturedSubject, CatalogReviewMemberCapture, CatalogReviewMemberDuration } from './adminCatalogReviewContract';

const fail = (status: number, code: string): never => { throw new AdminImportError(status, code); };
const isObject = (value: unknown): value is Record<string, unknown> => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const subjectKey = (credit: Pick<CatalogCredit, 'subjectType' | 'subjectId'>) => `${credit.subjectType}:${credit.subjectId}`;
const entryRoles: ReadonlySet<string> = new Set(['primary', 'featured']);

/** A member's file duration: the exact media duration when known, else its legacy whole-second text; null when neither is readable. */
export function catalogReviewMemberDuration(track: { mediaRepresentation?: unknown; duration?: unknown }): CatalogReviewMemberDuration | null {
    const exact = isObject(track.mediaRepresentation) ? track.mediaRepresentation.durationMs : undefined;
    if (Number.isSafeInteger(exact) && (exact as number) > 0) return { durationMs: exact as number, durationPrecisionMs: 0 };
    return legacyDurationEvidence(track.duration);
}

type CaptureInput = {
    reviewId: string; capturedAt: Date;
    album: { credits: CatalogCredit[] | null; expectedTracklist: ExpectedTracklistRow[] | null };
    members: { slotId: string; credits: CatalogCredit[] | null; attributionStatus: unknown; duration: CatalogReviewMemberDuration | null }[];
    subjects: ReadonlyMap<string, CatalogReviewCapturedSubject>;
};
/**
 * The capture and the draft values it implies, from Credits and records already read. Entries are built as review context is
 * (catalogReviewCredits), with names and MusicBrainz IDs from `subjects`; a member's entries are keyed per slot. Each captured
 * Credit names the entry showing it (`entryKey`), so a list is complete when every primary and featured Artist Credit has one;
 * unreadable Credits (null) are never complete, and Credits of other roles never count. The label is `first` only when the shown
 * label is the Album's first label Credit (a ready, named record), `none` without a label Credit, and `other` otherwise. An
 * attribution state other than documented or unknown is captured as null. Pure.
 */
export function catalogReviewCaptureOf(input: CaptureInput): { capture: CatalogReviewCapture; album: { artists: ImportArtistEntry[]; label: ImportLabelEntry | null }; memberArtists: Map<string, ImportArtistEntry[]> } {
    const names = (kind: CatalogCredit['subjectType']) => new Map([...input.subjects].filter(([key, subject]) => key.startsWith(`${kind}:`) && subject.name).map(([key, subject]) => [key.slice(kind.length + 1), subject.name]));
    const artistNames = names('artist'), organizationNames = names('organization');
    const musicBrainzIds = new Map([...input.subjects].flatMap(([key, subject]) => subject.musicBrainzId ? [[key, subject.musicBrainzId] as const] : []));
    const captured = (credits: CatalogCredit[] | null, artists: readonly ImportArtistEntry[], slotId?: string) => {
        const shown = new Set(artists.map(entry => entry.key));
        const list = credits?.map((credit): CatalogReviewCapturedCredit => {
            const key = catalogReviewEntryKey(input.reviewId, credit.creditId, slotId);
            return { creditId: credit.creditId, subjectType: credit.subjectType, subjectId: credit.subjectId, role: credit.role, joinPhrase: credit.joinPhrase ?? null,
                entryKey: shown.has(key) ? key : null, subject: input.subjects.get(subjectKey(credit)) ?? null };
        }) ?? null;
        return { credits: list, artistsComplete: list !== null && list.every(credit => credit.subjectType !== 'artist' || !entryRoles.has(credit.role) || credit.entryKey !== null) };
    };
    const album = catalogReviewCredits(input.reviewId, input.album.credits, artistNames, organizationNames, { musicBrainzIds });
    const albumCredits = captured(input.album.credits, album.artists);
    const firstLabel = input.album.credits?.find(credit => credit.subjectType === 'organization' && credit.role === 'label');
    const label = input.album.credits === null ? 'other' : !firstLabel ? 'none' : input.subjects.get(subjectKey(firstLabel))?.name ? 'first' : 'other';
    const memberArtists = new Map<string, ImportArtistEntry[]>();
    const members = input.members.map((member): CatalogReviewMemberCapture => {
        const { artists } = catalogReviewCredits(input.reviewId, member.credits, artistNames, organizationNames, { musicBrainzIds, slotId: member.slotId });
        memberArtists.set(member.slotId, artists);
        const attributionStatus = member.attributionStatus === 'documented' || member.attributionStatus === 'unknown' ? member.attributionStatus : null;
        return { slotId: member.slotId, ...captured(member.credits, artists, member.slotId), duration: member.duration, attributionStatus };
    });
    return { capture: { capturedAt: input.capturedAt, album: { ...albumCredits, label, expectedTracklist: input.album.expectedTracklist }, members }, album, memberArtists };
}

/** Reads an owner's Credits as the canonical Credit lifecycle does; an unreadable stored list is captured as null. */
async function capturedCredits(session: ClientSession, ownerType: 'album' | 'audioTrack', owner: any): Promise<CatalogCredit[] | null> {
    try { return await legacyCreditsForUnmigratedOwner(session, ownerType, String(owner._id), owner); }
    catch (error) { if (error instanceof CatalogCreditValidationError) return null; throw error; }
}

/**
 * Admits a review to metadata lookup: a format-1 or format-2 review is converted to format 3 in place, capturing, only while its
 * source is current, each member's duration and Disc Number (each source track that captured none gets the Track's current one,
 * which the draft shows where it showed none), the Album's and each member's ordered Credits as the canonical Credit lifecycle
 * reads them (an unmigrated member's legacy Artist links as legacy unspecified Credits) with each credited record's name,
 * MusicBrainz ID and revision, each member's attribution state, the label state, whether every primary and featured Artist Credit
 * is shown, and the Album's expected tracklist. The Album's entries and label are rebuilt from the Credits read now (unchanged
 * Credits keep their keys) and carry the records' MusicBrainz IDs. A format-3 review is only checked: its capture must be readable
 * and its source current; it is never captured again. Mutates `doc` only: a conversion advances its revision once and sets
 * `updatedAt`, adding no receipt (so no administrator change at an earlier revision goes stale), while a check changes nothing. The
 * caller persists it in the same transaction, guarded by the revision it read. Refusals: 404 not a review, 409 applied, 409 reload
 * for a newer format, an unreadable capture or a converted draft format 3 cannot hold, and 409 source changed for a source that is
 * not current.
 */
export async function catalogReviewForLookup(doc: AdminImportDocument, session: ClientSession): Promise<void> {
    if (doc.purpose !== 'catalogReview' || !doc.catalogSource) return fail(404, 'ADMIN_CATALOG_REVIEW_NOT_FOUND');
    if (doc.catalogApplied) return fail(409, 'ADMIN_CATALOG_REVIEW_APPLIED');
    if (!importDraftWritable(doc)) return fail(409, 'ADMIN_IMPORT_RELOAD_REQUIRED');
    if (importDraftVersion(doc) === CATALOG_REVIEW_DRAFT_V3) {
        storedDraftV2(doc);
        if (!readableCatalogCapture(doc)) return fail(409, 'ADMIN_IMPORT_RELOAD_REQUIRED');
        if ((await readCatalogReviewSource(doc, session)).status !== 'current') return fail(409, 'ADMIN_CATALOG_REVIEW_SOURCE_CHANGED');
        return;
    }
    convertLegacyCatalogReview(doc);
    const draft = storedDraftV2(doc), source = await readCatalogReviewSource(doc, session);
    if (source.status !== 'current') return fail(409, 'ADMIN_CATALOG_REVIEW_SOURCE_CHANGED');
    const albumCredits = await capturedCredits(session, 'album', source.album);
    const memberCredits: (CatalogCredit[] | null)[] = [];
    for (const track of source.tracks) memberCredits.push(await capturedCredits(session, 'audioTrack', track));
    const subjects = await readCatalogReviewSubjects([albumCredits, ...memberCredits].flatMap(credits => credits ?? []), session);
    const tracks = doc.catalogSource.tracks;
    const { capture, album, memberArtists } = catalogReviewCaptureOf({
        reviewId: doc._id.toHexString(), capturedAt: new Date(), subjects,
        album: { credits: albumCredits, expectedTracklist: storedExpectedTracklist(source.album)?.rows ?? null },
        members: tracks.map((track, index) => ({ slotId: track.slotId, credits: memberCredits[index], attributionStatus: source.tracks[index].attributionStatus, duration: catalogReviewMemberDuration(source.tracks[index]) }))
    });
    draft.album.artists = album.artists; draft.album.label = album.label;
    (draft.album as typeof draft.album & { expectedTracklist: ExpectedTracklistRow[] | null }).expectedTracklist = capture.album.expectedTracklist;
    tracks.forEach((track, index) => {
        if (catalogReviewSourceDisc(track)) return;
        // A source track that captured no Disc Number (created before they were captured) takes the Track's current one, which its
        // current revision proves unchanged since the review was created; the draft shows it where it showed none.
        track.discNumber = (adminCatalogEditableFields('audioTrack', source.tracks[index]).discNumber as number | null | undefined) ?? null;
        const member = draft.tracks.find(item => item?.slotId === track.slotId);
        if (member && member.discNumber === null) member.discNumber = track.discNumber;
    });
    for (const member of draft.tracks) if (member && typeof member === 'object') (member as typeof member & { artists: ImportArtistEntry[] }).artists = memberArtists.get(member.slotId) ?? [];
    doc.catalogCapture = capture; doc.draftVersion = CATALOG_REVIEW_DRAFT_V3;
    // A draft format 3 cannot hold (a stored track that is not an object) is refused before anything is stored.
    storedDraftV2(doc);
    // The draft changed without an administrator receipt, as a worker tick changes it: open confirmations see a new revision.
    doc.revision++; doc.updatedAt = new Date();
}
